:root {
  color-scheme: light;
  --ink: #263b35;
  --muted: #64736b;
  --paper: #fffdf7;
  --canvas: #f3eee3;
  --green: #39735b;
  --green-dark: #2d5d49;
  --gold: #e5b858;
  --line: #e6e2d7;
}
* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: var(--canvas);
  background-image: radial-gradient(#d9cfb8 1px, transparent 1px);
  background-size: 18px 18px;
  color: var(--ink);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
}
.planner {
  width: min(100%, 560px);
  padding: clamp(24px, 6vw, 44px);
  background: var(--paper);
  border: 1px solid #e9e2d4;
  border-radius: 18px;
  box-shadow: 0 12px 0 #ded5c3, 0 22px 48px #33443b18;
}
.header { text-align: center; }
.pixel-mark {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  margin: 0 auto 14px;
  background: var(--gold);
  border: 3px solid var(--ink);
  box-shadow: 4px 4px 0 var(--ink);
  font-weight: 800;
  font-size: 23px;
}
.eyebrow { margin: 0 0 6px; color: var(--green); font-weight: 750; font-size: 14px; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(25px, 7vw, 34px); line-height: 1.15; letter-spacing: -.04em; }
.intro { margin: 10px 0 28px; color: var(--muted); }
.form { display: grid; grid-template-columns: 1fr auto; gap: 9px 12px; align-items: center; }
.form label { font-weight: 650; }
.unit { color: var(--muted); font-weight: 500; }
input {
  width: 145px;
  min-height: 46px;
  padding: 9px 12px;
  border: 1px solid #c9d1c8;
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  font: inherit;
  text-align: right;
}
input:hover { border-color: var(--green); }
input:focus-visible, button:focus-visible, .table-wrap:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
button {
  grid-column: 1 / -1;
  min-height: 50px;
  margin-top: 12px;
  padding: 10px 16px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: var(--green);
  box-shadow: 0 4px 0 var(--ink);
  color: #fff;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: background .15s, transform .15s, box-shadow .15s;
}
button:hover { background: var(--green-dark); transform: translateY(-1px); }
button:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--ink); }
.message { min-height: 24px; margin: 14px 0 0; color: #a14335; font-weight: 600; }
.results { margin-top: 6px; }
.results[hidden] { display: none !important; }
h2 { margin: 4px 0 14px; font-size: 19px; }
.summary { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.summary > div { min-width: 0; padding: 12px 10px; border: 1px solid var(--line); border-radius: 9px; background: #f8f6ef; }
.summary-label { display: block; margin-bottom: 4px; color: var(--muted); font-size: 11px; line-height: 1.3; font-weight: 750; letter-spacing: .06em; }
.summary strong { font-size: clamp(16px, 4vw, 21px); overflow-wrap: anywhere; }
.table-title { margin-top: 25px; }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 9px; }
table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
th, td { padding: 9px 10px; text-align: right; white-space: nowrap; }
th { background: #edf2eb; color: var(--ink); font-size: 14px; }
th:first-child, td:first-child { text-align: left; }
tbody tr:nth-child(even) { background: #faf9f4; }
td { border-top: 1px solid #efede6; }
.note { margin: 10px 0 0; color: var(--muted); font-size: 14px; }
footer { margin-top: 25px; color: var(--muted); text-align: center; font-size: 14px; }
footer span { color: #bb8a26; }
@media (max-width: 420px) {
  body { padding: 20px 12px; }
  .planner { padding: 24px 18px; }
  .summary { gap: 5px; }
  .summary > div { padding: 10px 7px; }
  .summary-label { font-size: 10px; }
  th, td { padding: 8px 7px; }
}

const form = document.querySelector("#planner-form");
const results = document.querySelector("#results");
const message = document.querySelector("#message");
const schedule = document.querySelector("#schedule");
const money = new Intl.NumberFormat(undefined, { style: "currency", currency: "USD" });

function calculate(goal, deposit, annualRate) {
  const monthlyRate = annualRate / 100 / 12;
  let balance = 0;
  let totalInterest = 0;
  const rows = [];

  while (balance < goal && rows.length < 1200) {
    const contribution = Math.min(deposit, goal - balance);
    balance += contribution;
    const interest = balance * monthlyRate;
    balance += interest;
    totalInterest += interest;
    if (balance > goal) {
      totalInterest -= balance - goal;
      balance = goal;
    }
    rows.push({ month: rows.length + 1, contribution, interest: Math.max(0, interest - Math.max(0, balance - goal)), balance });
  }
  return { rows, totalInterest };
}

form.addEventListener("submit", (event) => {
  event.preventDefault();
  message.textContent = "";
  const goal = Number(form.elements.goal.value);
  const deposit = Number(form.elements.deposit.value);
  const rate = Number(form.elements.rate.value);

  if (!Number.isFinite(goal) || goal <= 0 || !Number.isFinite(deposit) || deposit < 0 || !Number.isFinite(rate) || rate < 0 || rate > 100) {
    results.hidden = true;
    message.textContent = "Enter a positive goal, a nonnegative monthly deposit, and a rate from 0% to 100%.";
    return;
  }
  if (deposit === 0 && rate === 0) {
    results.hidden = true;
    message.textContent = "With no monthly deposit and no interest, the goal cannot be reached.";
    return;
  }

  const { rows, totalInterest } = calculate(goal, deposit, rate);
  if (!rows.length || rows[rows.length - 1].balance < goal) {
    results.hidden = true;
    message.textContent = "This plan would take more than 1,200 months to reach the goal. Increase your deposit or rate.";
    return;
  }

  document.querySelector("#months-result").textContent = `${rows.length} ${rows.length === 1 ? "month" : "months"}`;
  document.querySelector("#interest-result").textContent = money.format(totalInterest);
  document.querySelector("#balance-result").textContent = money.format(goal);
  schedule.replaceChildren(...rows.map((row) => {
    const tr = document.createElement("tr");
    for (const value of [row.month, money.format(row.contribution), money.format(row.interest), money.format(row.balance)]) {
      const td = document.createElement("td");
      td.textContent = value;
      tr.append(td);
    }
    return tr;
  }));
  results.hidden = false;
});
